class ProfileScreen extends StatelessWidget{const ProfileScreen({super.key});@override Widget build(BuildContext context){final loc=AppLocalizations.of(context),lp=context.watch<LocaleProvider>();final fa=lp.locale.languageCode=='fa',font=fa?'Vazir':'Poppins',api=context.read<LifeMateApiClient>();void open(Widget p)=>Navigator.of(context).push(MaterialPageRoute<void>(builder:(_)=>p));final profile=LifeMateSharedProfileScreen(apiClient:api,theme:LifeMateProfileThemeData(background:AppColors.background,accent:AppColors.primary,titleColor:AppColors.darkBlue,secondaryText:AppColors.textSecondary,cardBackground:AppColors.cardBackground),labels:LifeMateProfileLabels(personalInfo:loc['profile_personal_info']??(fa?'اطلاعات شخصی':'Personal information'),healthProfile:loc['profile_health_profile']??(fa?'پرونده سلامت':'Health profile'),careManagement:loc['profile_caregivers']??(fa?'مراقبان':'Caregivers'),appSettings:loc['profile_app_settings']??(fa?'تنظیمات برنامه':'App settings'),referral:loc['profile_referral_code']??(fa?'کد معرف':'Referral code'),support:fa?'پشتیبانی آنلاین':'Online Support',logout:loc['profile_logout']??(fa?'خروج از حساب':'Sign out'),subscriptionTitle:loc['profile_no_subscription']??(fa?'اشتراک':'Subscription'),manageSubscriptions:loc['profile_buy_plan']??(fa?'مدیریت اشتراک‌ها':'Manage subscriptions'),referralSubtitle:fa?'در دست توسعه':'Coming soon',supportSubtitle:fa?'گفت‌وگوی مستقیم با تیم پشتیبانی':'Chat directly with support'),fontFamily:font,appName:'WellMate',versionLabel:'WellMate $wellMateAppVersion'.toPersianDigit(fa),fallbackUserName:fa?'کاربر LifeMate':'LifeMate user',isPersian:fa,onNotifications:()=>open(NotificationCenterScreen()),onEditProfile:()=>open(EditableProfileScreen()),onHealthProfile:()=>open(HealthRecordScreen()),onCareManagement:()=>open(LifeMateCareAccessInventoryScreen(apiClient:api,role:LifeMateCareAccessRole.patient,accent:AppColors.primary,background:AppColors.background,ink:AppColors.darkBlue,onManage:()=>open(CareAccessPhone